{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE MAPLEMONK.MYNTRA_CHASE_PPMP_ORDERS_MYNTRA_FACT_ITEMS AS select ms.*, mr.quantity return_quantity, case when cast(mr.quantity as int64) >0 THEN ms.selling_price end as return_value, mr.type, mr.return_created_date, mr.return_reason, from(SELECT \'MYNTRA CHASE PPMP\' AS shop_name, \'MYNTRA CHASE PPMP\' AS marketplace, \'MYNTRA CHASE PPMP\' AS CHANNEL, \'MYNTRA CHASE PPMP\' AS SOURCE, CAST(order_id_fk AS STRING) AS order_id_fk, CAST(seller_order_id AS STRING) AS Order_id, CAST(replace(store_order_id,\'\\'\',\'\') AS STRING) AS store_order_id, CAST(order_line_id AS INT64) AS order_line_id, CAST(order_tracking_number AS STRING) AS order_tracking_number, CAST(sku_id AS STRING) AS sku_id, CAST(myntra_sku_code AS STRING) AS myntra_sku_code, CAST(seller_sku_code AS STRING) AS seller_sku_code, CAST(style_id AS INT64) AS style_id, CAST(size AS STRING) Size, UPPER(CAST(style_name AS STRING)) AS PRODUCT_NAME, CAST(brand AS STRING) AS BRAND, CAST(vendor_article_number AS STRING) AS SKU, CAST(article_type AS STRING) Product_category, CAST(state AS STRING) AS STATE, CAST(city AS STRING) AS CITY, CAST(zipcode AS STRING) AS zipcode, CAST(warehouse_id AS INT64) AS warehouse_id, CAST(seller_warehouse_id AS INT64) AS seller_warehouse_id, CAST(courier_code AS STRING) AS courier_code, CASE WHEN created_on = \'\' THEN NULL ELSE DATE(PARSE_TIMESTAMP(\'%Y-%m-%d %H:%M:%S\', SUBSTR (created_on, 1, 19))) END AS created_date, CASE WHEN packed_on = \'\' THEN NULL ELSE DATE(PARSE_TIMESTAMP(\'%Y-%m-%d %H:%M:%S\', SUBSTR(packed_on, 1, 19))) END AS packed_date, CASE WHEN inscanned_on = \'\' THEN NULL ELSE DATE(PARSE_TIMESTAMP(\'%Y-%m-%d %H:%M:%S\', SUBSTR(inscanned_on, 1, 19))) END AS inscanned_date, CASE WHEN shipped_on = \'\' THEN NULL ELSE DATE(PARSE_TIMESTAMP(\'%Y-%m-%d %H:%M:%S\', SUBSTR(shipped_on, 1, 19))) END AS shipped_date, CASE WHEN delivered_on = \'\' THEN NULL ELSE DATE(PARSE_TIMESTAMP(\'%Y-%m-%d %H:%M:%S\', SUBSTR(delivered_on, 1, 19))) END AS delivered_date, CASE WHEN cancelled_on = \'\' THEN NULL ELSE DATE(PARSE_TIMESTAMP(\'%Y-%m-%d %H:%M:%S\', SUBSTR(cancelled_on, 1, 19))) END AS cancelled_date, CASE WHEN rto_creation_date = \'\' THEN NULL ELSE DATE(PARSE_TIMESTAMP(\'%Y-%m-%d %H:%M:%S\', SUBSTR(rto_creation_date, 1, 19))) END AS rto_creation_date, CASE WHEN return_creation_date = \'\' THEN NULL ELSE DATE(PARSE_TIMESTAMP(\'%Y-%m-%d %H:%M:%S\', SUBSTR(return_creation_date, 1, 19))) END AS return_creation_date, CAST(total_mrp AS FLOAT64) AS total_mrp, CAST(final_amount AS FLOAT64) AS selling_price, CAST(1 AS INT64) AS QUANTITY, CAST(discount AS FLOAT64) AS discount, CAST(coupon_discount AS FLOAT64) AS coupon_discount, CAST(tax_recovery AS FLOAT64) AS tax_recovery, CAST(shipping_charge AS FLOAT64) AS shipping_charge, CAST(gift_charge AS FLOAT64) AS gift_charge, CAST(cancellation_reason AS STRING) AS cancellation_reason, CASE WHEN UPPER(ORDER_STATUS) = \'C\' THEN \'DELIVERED\' WHEN UPPER(ORDER_STATUS) = \'F\' THEN \'CANCELLED\' WHEN UPPER(ORDER_STATUS) = \'L\' THEN \'LOST\' WHEN UPPER(ORDER_STATUS) = \'PK\' THEN \'PACKED\' WHEN UPPER(ORDER_STATUS) = \'SH\' THEN \'SHIPPED\' WHEN UPPER(ORDER_STATUS) = \'RTO\' THEN \'RTO\' WHEN UPPER(ORDER_STATUS) = \'WP\' THEN \'OTHERS\' END AS order_status, CAST(order_release_id AS STRING) AS order_release_id, ROW_NUMBER() OVER (PARTITION BY order_id_fk, seller_order_id ORDER BY created_on DESC) as rn, FROM `MAPLEMONK.myntra_chase_ppmp_myntra_custom_orders`) ms LEFT JOIN( select model, myntra_sku_code, seller_sku_code, style_id, sku_id, brand, order_created_date, order_delivered_date, return_created_date, is_refunded, order_line_id, seller_order_id, type, quantity, return_id, return_reason, warehouse_id from maplemonk.myntra_chase_ppmp_myntra_custom_returns where lower(type) = \'return\' qualify row_number() over(partition by myntra_sku_code,seller_sku_code,return_created_date,seller_order_id order by return_created_date desc)=1 ) mr ON date(ms.created_date) = date(mr.order_created_date) AND ms.Order_id = mr.seller_order_id AND ms.myntra_sku_code = mr.myntra_sku_code AND ms.seller_sku_code = mr.seller_sku_code where ms.rn=1; CREATE OR REPLACE TABLE MAPLEMONK.MYNTRA_PANTS_PPMP_ORDERS_MYNTRA_FACT_ITEMS AS select ms.*, mr.quantity return_quantity, case when cast(mr.quantity as int64) >0 THEN ms.selling_price end as return_value, mr.type, mr.return_created_date, mr.return_reason, from(SELECT \'MYNTRA PANTS PPMP\' AS shop_name, \'MYNTRA PANTS PPMP\' AS marketplace, \'MYNTRA PANTS PPMP\' AS CHANNEL, \'MYNTRA PANTS PPMP\' AS SOURCE, CAST(order_id_fk AS STRING) AS order_id_fk, CAST(seller_order_id AS STRING) AS Order_id, CAST(replace(store_order_id,\'\\'\',\'\') AS STRING) AS store_order_id, CAST(order_line_id AS INT64) AS order_line_id, CAST(order_tracking_number AS STRING) AS order_tracking_number, CAST(sku_id AS STRING) AS sku_id, CAST(myntra_sku_code AS STRING) AS myntra_sku_code, CAST(seller_sku_code AS STRING) AS seller_sku_code, CAST(style_id AS INT64) AS style_id, CAST(size AS STRING) Size, UPPER(CAST(style_name AS STRING)) AS PRODUCT_NAME, CAST(brand AS STRING) AS BRAND, CAST(vendor_article_number AS STRING) AS SKU, CAST(article_type AS STRING) Product_category, CAST(state AS STRING) AS STATE, CAST(city AS STRING) AS CITY, CAST(zipcode AS STRING) AS zipcode, CAST(warehouse_id AS INT64) AS warehouse_id, CAST(seller_warehouse_id AS INT64) AS seller_warehouse_id, CAST(courier_code AS STRING) AS courier_code, CASE WHEN created_on = \'\' THEN NULL ELSE DATE(PARSE_TIMESTAMP(\'%Y-%m-%d %H:%M:%S\', SUBSTR (created_on, 1, 19))) END AS created_date, CASE WHEN packed_on = \'\' THEN NULL ELSE DATE(PARSE_TIMESTAMP(\'%Y-%m-%d %H:%M:%S\', SUBSTR(packed_on, 1, 19))) END AS packed_date, CASE WHEN inscanned_on = \'\' THEN NULL ELSE DATE(PARSE_TIMESTAMP(\'%Y-%m-%d %H:%M:%S\', SUBSTR(inscanned_on, 1, 19))) END AS inscanned_date, CASE WHEN shipped_on = \'\' THEN NULL ELSE DATE(PARSE_TIMESTAMP(\'%Y-%m-%d %H:%M:%S\', SUBSTR(shipped_on, 1, 19))) END AS shipped_date, CASE WHEN delivered_on = \'\' THEN NULL ELSE DATE(PARSE_TIMESTAMP(\'%Y-%m-%d %H:%M:%S\', SUBSTR(delivered_on, 1, 19))) END AS delivered_date, CASE WHEN cancelled_on = \'\' THEN NULL ELSE DATE(PARSE_TIMESTAMP(\'%Y-%m-%d %H:%M:%S\', SUBSTR(cancelled_on, 1, 19))) END AS cancelled_date, CASE WHEN rto_creation_date = \'\' THEN NULL ELSE DATE(PARSE_TIMESTAMP(\'%Y-%m-%d %H:%M:%S\', SUBSTR(rto_creation_date, 1, 19))) END AS rto_creation_date, CASE WHEN return_creation_date = \'\' THEN NULL ELSE DATE(PARSE_TIMESTAMP(\'%Y-%m-%d %H:%M:%S\', SUBSTR(return_creation_date, 1, 19))) END AS return_creation_date, CAST(total_mrp AS FLOAT64) AS total_mrp, CAST(final_amount AS FLOAT64) AS selling_price, CAST(1 AS INT64) AS QUANTITY, CAST(discount AS FLOAT64) AS discount, CAST(coupon_discount AS FLOAT64) AS coupon_discount, CAST(tax_recovery AS FLOAT64) AS tax_recovery, CAST(shipping_charge AS FLOAT64) AS shipping_charge, CAST(gift_charge AS FLOAT64) AS gift_charge, CAST(cancellation_reason AS STRING) AS cancellation_reason, CASE WHEN UPPER(ORDER_STATUS) = \'C\' THEN \'DELIVERED\' WHEN UPPER(ORDER_STATUS) = \'F\' THEN \'CANCELLED\' WHEN UPPER(ORDER_STATUS) = \'L\' THEN \'LOST\' WHEN UPPER(ORDER_STATUS) = \'PK\' THEN \'PACKED\' WHEN UPPER(ORDER_STATUS) = \'SH\' THEN \'SHIPPED\' WHEN UPPER(ORDER_STATUS) = \'RTO\' THEN \'RTO\' WHEN UPPER(ORDER_STATUS) = \'WP\' THEN \'OTHERS\' END AS order_status, CAST(order_release_id AS STRING) AS order_release_id, ROW_NUMBER() OVER (PARTITION BY order_id_fk, seller_order_id ORDER BY created_on DESC) as rn, FROM `MAPLEMONK.myntra_pants_ppmp_myntra_custom_orders`) ms LEFT JOIN( select model, myntra_sku_code, seller_sku_code, style_id, sku_id, brand, order_created_date, order_delivered_date, return_created_date, is_refunded, order_line_id, seller_order_id, type, quantity, return_id, return_reason, warehouse_id from maplemonk.myntra_pants_ppmp_myntra_custom_returns where lower(type) = \'return\' qualify row_number() over(partition by myntra_sku_code,seller_sku_code,return_created_date,seller_order_id order by return_created_date desc)=1 ) mr ON date(ms.created_date) = date(mr.order_created_date) AND ms.Order_id = mr.seller_order_id AND ms.myntra_sku_code = mr.myntra_sku_code AND ms.seller_sku_code = mr.seller_sku_code where ms.rn=1; create or replace table maplemonk.Miss_Chase_Myntra_fact_items as select m.*, upper(p.name) as product_name_final, upper(coalesce(p.category,m.product_category)) as mapped_category, upper(p.sub_category) as product_sub_category, upper(p.commonsku) as commonsku, upper(p.style) as style, from (select * from MAPLEMONK.MYNTRA_CHASE_PPMP_ORDERS_MYNTRA_FACT_ITEMS union all select * from MAPLEMONK.MYNTRA_PANTS_PPMP_ORDERS_MYNTRA_FACT_ITEMS ) m left join (select * from (select upper(replace(MYNTRA_SID,\' \',\'\')) skucode, replace(style_code,\' \',\'\') as style, cast(null as string) category, cast(null as string) sub_category , replace(sku_code,\' \',\'\') as commonsku, upper(trim(product_name)) name, row_number()over (partition by upper(replace(MYNTRA_SID,\' \',\'\')) order by length(ifnull(upper(replace(MYNTRA_SID,\' \',\'\')),\'\')) desc) rw from misschase-maplemonk-wh.maplemonk.misschase_google_sheet_sku_master where not (lower(MYNTRA_SID) like (\'not live on myntra\')) ) where rw = 1 ) p on lower(replace(m.sku_id,\' \',\'\')) = lower(p.skucode) ;",
